-- ============== SCHEMA ==============

CREATE TABLE IF NOT EXISTS employees (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  active INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS code_table (
  code TEXT PRIMARY KEY,
  day_label TEXT,
  night_label TEXT
);

CREATE TABLE IF NOT EXISTS seat_template (
  seat INTEGER NOT NULL,
  dow TEXT NOT NULL,
  period TEXT,
  code TEXT,
  PRIMARY KEY (seat, dow)
);

CREATE TABLE IF NOT EXISTS anchor_week (
  emp_id INTEGER PRIMARY KEY,
  seat INTEGER NOT NULL,
  grp TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS shifts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  date TEXT NOT NULL,
  dow TEXT NOT NULL,
  emp_id INTEGER NOT NULL,
  emp_name TEXT NOT NULL,
  period TEXT NOT NULL,
  code TEXT NOT NULL,
  label TEXT NOT NULL,
  swappable INTEGER NOT NULL DEFAULT 1,
  UNIQUE(date, emp_id)
);
CREATE INDEX IF NOT EXISTS idx_shifts_date ON shifts(date);
CREATE INDEX IF NOT EXISTS idx_shifts_emp ON shifts(emp_id);

CREATE TABLE IF NOT EXISTS swap_requests (
  id TEXT PRIMARY KEY,
  created_at TEXT NOT NULL,
  requester_id INTEGER NOT NULL,
  requester_name TEXT NOT NULL,
  target_id INTEGER NOT NULL,
  target_name TEXT NOT NULL,
  my_date TEXT NOT NULL,
  my_dow TEXT NOT NULL,
  my_code TEXT NOT NULL,
  my_period TEXT NOT NULL,
  target_date TEXT NOT NULL,
  target_dow TEXT NOT NULL,
  target_code TEXT NOT NULL,
  target_period TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT '대기',
  memo TEXT,
  processed_at TEXT
);

-- ============== SEED: employees ==============
